/// Find a stable intent name.
pub fn intent(name: &str) -> Option<&'static IntentSpec> {
    INTENTS.iter().find(|spec| spec.name == name)
}

/// Find a stable read name.
pub fn read(name: &str) -> Option<&'static ReadSpec> {
    READS.iter().find(|spec| spec.name == name)
}
